from lib import *
S = SS('j279')
steps = [
    step("同一个查询(age ≥ 30 且 city = Beijing,按 name 排序)用 JPQL 与 Criteria 写,发给 PostgreSQL 的 SQL 完全相同:where p1_0.age>=? and p1_0.city=? order by p1_0.name fetch first ? rows only——Criteria 里的值 30 与 \"Beijing\" 也是绑定参数。显式写 cb.literal(\"Beijing\") 才会被内联成 where p1_0.city='Beijing'(和 JPQL 里直接写字面量一样)。cb.literal 带单引号的输入 x' or '1'='1 被转义成 'x'' or ''1''=''1',返回 0 行,不是 SQL 注入,但每个不同的字面量都会产生不同的 SQL 文本。", t=tl(S(1)), done=lidx(S(1), 'JPQL:select p from Person p where p.age', 'Criteria:cb.ge(age, 30)'), mark=lidx(S(1), 'cb.literal(\"Beijing\")', 'x\' or \'1\'=\'1', '返回 0 行', 'JPQL 里直接写字面量'), kv=KV([['JPQL 与 Criteria(带值的 equal / ge)', '同一条 SQL,值是绑定参数'], ['cb.literal', '内联成 SQL 字面量,单引号被转义']], ['JPQL 与 Criteria(带值的 equal / ge)'])),
    step("写错属性名:Criteria 用字符串 r.get(\"agee\") 在构建并执行时才抛 PathElementException(Could not resolve attribute 'agee' of 'Person');cb.equal(r.get(\"age\"), \"not-a-number\") 抛 CoercionException(Error coercing value)——类型错误也是运行时才发现。用 hibernate-jpamodelgen 生成的静态元模型 r.get(Person_.age):属性有类型信息(Person_.age 的 Java 类型是 int),正常执行返回 40 行。", t=tl(S(2)), done=lidx(S(2), 'r.get(\"agee\")', 'cb.equal(r.get(\"age\")'), mark=lidx(S(2), 'Person_.age'), kv=KV([['r.get(\"agee\")', '运行时 PathElementException'], ['age 与字符串比较', '运行时 CoercionException'], ['r.get(Person_.age)', '有类型的元模型属性,正常执行']], ['r.get(\"agee\")'])),
    step("构建与执行的开销(每种做法 5000 次 select … where id = ?,单行结果,取第二轮,含数据库往返):JPQL 字符串 + setParameter 61.5 µs/次(查询计划缓存命中 10000 / 未命中 0);每次重新构建 CriteriaQuery 77.0 µs;CriteriaQuery 构建一次、用 ParameterExpression 复用 67.3 µs;命名查询 59.8 µs。Criteria 查询的查询计划缓存命中 / 未命中都是 0——它们不经过 HQL 的查询计划缓存;每次重新构建比 JPQL 多约 15.5 µs(约 25%),构建一次复用只多约 5.8 µs。", t=tl(S(3)), done=lidx(S(3), 'JPQL 字符串 + setParameter', '每次重新构建 CriteriaQuery'), mark=lidx(S(3), 'CriteriaQuery 构建一次', '命名查询'), b=bars([['JPQL 字符串', 61.5, '61.5 µs'], ['Criteria 每次构建', 77.0, '77.0 µs'], ['Criteria 构建一次复用', 67.3, '67.3 µs'], ['命名查询', 59.8, '59.8 µs']], 77, done=[0, 1, 2, 3]), kv=KV([['JPQL / 命名查询', '61.5 / 59.8 µs,命中查询计划缓存'], ['Criteria 每次构建', '77.0 µs,不经过查询计划缓存'], ['Criteria 复用', '67.3 µs']], ['Criteria 每次构建'])),
    step("动态条件:Criteria 按条件拼接,8 种条件组合各执行 3 次(共 24 次),发给数据库的不同 SQL 文本共 8 种(从没有 where 到 name like ? escape ''、age>=? 等不同形状);用一条“可选参数”JPQL(:p is null or p.x = :p)写同样 8 种组合 × 3 次,只有 1 种 SQL 文本,预编译语句可以复用,代价是执行计划是通用的,(? is null or col = ?) 往往用不上索引。Criteria 的动态拼接换来更好的计划,代价是更多不同的 SQL 文本。", t=tl(S(4)), done=lidx(S(4), '8 种条件组合各执行 3 次', '例 1'), mark=lidx(S(4), '例 2', '例 3', '可选参数'), b=bars([['Criteria 动态拼接:不同 SQL 文本', 8, '8 种'], ['可选参数 JPQL:不同 SQL 文本', 1, '1 种']], 8, done=[0, 1]), kv=KV([['Criteria 动态拼接', '8 种组合 → 8 种 SQL 文本'], ['可选参数 JPQL', '8 种组合 → 1 种 SQL 文本']], ['Criteria 动态拼接'])),
    step("CriteriaUpdate 与 CriteriaDelete:CriteriaUpdate 把 city = Beijing 的 active 设为 false,影响 500 行;CriteriaDelete 删除 age < 20 的行,影响 80 行(用 executeUpdate 执行)。它们和 JPQL 的批量更新一样直接发到数据库,不经过持久化上下文的脏检查,也不会同步内存里的实体。", t=tl(S(5)), done=lidx(S(5), 'CriteriaUpdate:把 city'), mark=lidx(S(5), 'CriteriaDelete:删除'), kv=KV([['CriteriaUpdate', '影响 500 行'], ['CriteriaDelete', '影响 80 行']], ['CriteriaUpdate'])),
    step("静态元模型在编译期的反馈:把 r.get(Person_.age) 写成 r.get(Person_.agee),javac 退出码 1,错误是 cannot find symbol: variable agee——属性名的拼写错误在编译时就暴露。但同一行里的 cb.equal(r.get(Person_.age), \"x\")(int 与字符串)没有被编译器拦住,因为 cb.equal 接受任意对象;类型检查要靠 cb.gt 之类带类型的方法。", t=tl(S(6)), done=lidx(S(6), 'javac 退出码 1'), mark=lidx(S(6), 'cannot find symbol', 'symbol:   variable agee'), kv=KV([['Person_.agee(拼写错误)', '编译错误:cannot find symbol'], ['cb.equal(int 属性, \"x\")', '编译器不拦截(接受 Object)']], ['Person_.agee(拼写错误)'])),
]
A = mkartj('j279', 279, 'Java,JPA,Hibernate,Criteria API,静态元模型,动态查询,PostgreSQL,真实验证,动画演示',
    '在 Hibernate 6.6.4 + 真实 PostgreSQL 上实测 JPA Criteria API:与 JPQL 发出同样的 SQL(值是绑定参数,cb.literal 才内联);字符串属性名拼错与类型错误在运行时才报错,静态元模型把拼写错误提前到编译期;每次重新构建比 JPQL 慢约 25%(77.0 vs 61.5 µs)且不经过查询计划缓存;8 种动态条件组合产生 8 种 SQL 文本。',
    'Criteria API 的卖点是“类型化”和“程序化构造”。这篇用真实的 SQL 与计时量出它到底带来什么:SQL 与 JPQL 一样、运行时与编译期的错误反馈、构建开销与查询计划缓存、动态条件对 SQL 文本数量的影响,以及它没有拦住的类型错误。',
    [('同一条 SQL', 'JPQL 与 Criteria(cb.ge / cb.equal)发给 PostgreSQL 的 SQL:where p1_0.age>=? and p1_0.city=?'), ('77.0 vs 61.5 µs', '每次重新构建 CriteriaQuery 与 JPQL 字符串查询的单次耗时(含数据库往返)'), ('8 种 vs 1 种', '8 种条件组合的 Criteria 动态查询与“可选参数”JPQL 发给数据库的不同 SQL 文本数')],
    [('JPQL 与 Criteria 的 SQL', None), ('运行时错误', None), ('构建开销', None), ('动态条件', None), ('CriteriaUpdate / Delete', None), ('静态元模型的编译期反馈', None)],
    steps, [ENV_J + '。Hibernate ORM 6.6.4.Final + hibernate-jpamodelgen 6.6.4.Final、PostgreSQL JDBC 42.7.4、本机 PostgreSQL 16.15;开销数字是 5000 次循环第二轮的平均值,不是 JMH', '没有验证:hibernate.criteria.plan_cache_enabled(6.4+ 的 Criteria 计划缓存开关)打开后的开销、Querydsl / jOOQ 等其它类型安全查询构建器、fetch join 与分页的组合、Spring Data JPA 的 Specification、更复杂的子查询与窗口函数'], 'JPA Criteria API')
